from __future__ import annotations

import json
import os
import sys
from pathlib import Path


TASK_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_ROOT / "source"
CASE_MANIFEST = TASK_ROOT / "fixtures" / "abacus_relax_case.json"
REPORT_PATH = TASK_ROOT / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_PATH.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def evaluate_case(report: dict[str, object], kind: str) -> bool:
    frame_alignment_ok = bool(report["frame_alignment_ok"])
    trajectory_span_ok = bool(report["trajectory_span_ok"])
    virials_present = bool(report["virials_present"])
    stress_frames = int(report["stress_frames"])

    if kind == "trajectory_span":
        return frame_alignment_ok and trajectory_span_ok
    if kind == "frame_alignment":
        return frame_alignment_ok
    if kind == "frame_alignment_no_stress":
        return frame_alignment_ok and not virials_present and stress_frames == 0
    raise ValueError(f"Unknown public case kind: {kind!r}")


def main() -> int:
    try:
        os.environ.setdefault("PYTHONHASHSEED", "0")
        sys.path.insert(0, str(TASK_ROOT))
        sys.path.insert(0, str(SOURCE_ROOT))

        from workflow import run

        manifest = json.loads(CASE_MANIFEST.read_text(encoding="utf-8"))
        if "cases" in manifest:
            case_specs = manifest["cases"]
        else:
            case_specs = [
                {
                    "name": "public_case",
                    "case_dir": manifest["case_dir"],
                    "kind": "trajectory_span",
                }
            ]

        case_reports: list[dict[str, object]] = []
        for case in case_specs:
            case_dir = TASK_ROOT / "fixtures" / case["case_dir"]
            report = run(case_dir)
            case_ok = evaluate_case(report, case["kind"])
            case_reports.append(
                {
                    "name": case["name"],
                    "kind": case["kind"],
                    "case_ok": case_ok,
                    "observation": report,
                }
            )

    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    status = "post_fix_success" if all(case["case_ok"] for case in case_reports) else "pre_fix_expected_failure"
    return write_report(
        {
            "schema_version": "1.0",
            "status": status,
            "cases": case_reports,
        },
        0 if status == "post_fix_success" else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())

